import { promisify } from 'node:util';
import { unzip, unzipSync } from 'node:zlib';
const unzipPromise = promisify(unzip);
export const decompress = async (data) => 
// oxlint-disable-next-line typescript/no-unsafe-type-assertion
JSON.parse((await unzipPromise(data)).toString());
// oxlint-disable-next-line typescript/no-unnecessary-type-parameters
export const decompressSync = (data) => 
// oxlint-disable-next-line typescript/no-unsafe-type-assertion
JSON.parse(unzipSync(data).toString());
